mkdir test-lab && cd test-lab
npm init -y
npm pkg set type=module
npm install -D vitest

// discount.js
export function discount(price, percent) {
  return price - (price * percent) / 100;
}

// discount.test.js
import { describe, it, expect } from "vitest";
import { discount } from "./discount.js";

describe("discount", () => {
  it("снимает 10% с 200", () => {
    expect(discount(200, 10)).toBe(180);
  });
  it("без скидки возвращает цену", () => {
    expect(discount(200, 0)).toBe(200);
  });
  it("не уходит ниже нуля", () => {
    expect(discount(200, 150)).toBe(0);
  });
});

npx vitest run
